"""French and Kinyarwanda versions of the Ikimina guide. Same structure as ikimina_guide_content.py: the English file says which
blocks each section has (screens, steps, bullets, tables, notes); this file supplies the words. Menu names are the ones the app itself shows."""
import ikimina_guide_content as EN

def _merge(spec):
    out = []
    for s in EN.SECTIONS:
        t = spec[s['id']]; k = {'shots': 0, 'steps': 0, 'bullets': 0}; blocks = []
        for b in s['blocks']:
            if b[0] == 'shots':
                caps = t['shots'][k['shots']]; k['shots'] += 1
                blocks.append(('shots', [(kind, f, ttl, cap) for (kind, f, _a, _b), (ttl, cap) in zip(b[1], caps)]))
            elif b[0] == 'steps': blocks.append(('steps', t['steps'][k['steps']])); k['steps'] += 1
            elif b[0] == 'bullets': blocks.append(('bullets', t['bullets'][k['bullets']])); k['bullets'] += 1
            elif b[0] == 'call': blocks.append(('call', b[1], t['call']))
            elif b[0] == 'table': blocks.append(('table', t['table'][0], t['table'][1]))
        out.append(dict(id=s['id'], kick=t['kick'], title=t['title'], lead=t['lead'], blocks=blocks))
    return out

